89	/**
90	 * If two dataZoomModels has the same axis controlled, we say that they are 'linked'.
91	 * This function finds all linked dataZoomModels start from the given payload.
92	 */
93	export function findEffectedDataZooms(ecModel: GlobalModel, payload: Payload): DataZoomModel[] {
94	
95	    // Key: `DataZoomAxisDimension`
96	    const axisRecords = createHashMap<boolean[], DataZoomAxisDimension>();
97	    const effectedModels: DataZoomModel[] = [];
98	    // Key: uid of dataZoomModel
99	    const effectedModelMap = createHashMap<boolean>();
100	
101	    // Find the dataZooms specified by payload.
102	    ecModel.eachComponent(
103	        { mainType: 'dataZoom', query: payload },
104	        function (dataZoomModel: DataZoomModel) {
105	            if (!effectedModelMap.get(dataZoomModel.uid)) {
106	                addToEffected(dataZoomModel);
107	            }
108	        }
109	    );
110	
111	    // Start from the given dataZoomModels, travel the graph to find
112	    // all of the linked dataZoom models.
113	    let foundNewLink;
114	    do {
115	        foundNewLink = false;
116	        ecModel.eachComponent('dataZoom', processSingle);
117	    }
118	    while (foundNewLink);
119	
120	    function processSingle(dataZoomModel: DataZoomModel): void {
121	        if (!effectedModelMap.get(dataZoomModel.uid) && isLinked(dataZoomModel)) {
122	            addToEffected(dataZoomModel);
123	            foundNewLink = true;
124	        }
125	    }
126	
127	    function addToEffected(dataZoom: DataZoomModel): void {
128	        effectedModelMap.set(dataZoom.uid, true);
129	        effectedModels.push(dataZoom);
130	        markAxisControlled(dataZoom);
131	    }
132	
133	    function isLinked(dataZoomModel: DataZoomModel): boolean {
134	        let isLink = false;
135	        dataZoomModel.eachTargetAxis(function (axisDim, axisIndex) {
136	            const axisIdxArr = axisRecords.get(axisDim);
137	            if (axisIdxArr && axisIdxArr[axisIndex]) {
138	                isLink = true;
139	            }
140	        });
141	        return isLink;
142	    }
143	
144	    function markAxisControlled(dataZoomModel: DataZoomModel) {
145	        dataZoomModel.eachTargetAxis(function (axisDim, axisIndex) {
146	            (
147	                axisRecords.get(axisDim) || axisRecords.set(axisDim, [])
148	            )[axisIndex] = true;
149	        });
150	    }
151	
152	    return effectedModels;
153	}
