155	/**
156	 * Find the first target coordinate system.
157	 * Available after model built.
158	 *
159	 * @return Like {
160	 *                  grid: [
161	 *                      {model: coord0, axisModels: [axis1, axis3], coordIndex: 1},
162	 *                      {model: coord1, axisModels: [axis0, axis2], coordIndex: 0},
163	 *                      ...
164	 *                  ],  // cartesians must not be null/undefined.
165	 *                  polar: [
166	 *                      {model: coord0, axisModels: [axis4], coordIndex: 0},
167	 *                      ...
168	 *                  ],  // polars must not be null/undefined.
169	 *                  singleAxis: [
170	 *                      {model: coord0, axisModels: [], coordIndex: 0}
171	 *                  ]
172	 *              }
173	 */
174	export function collectReferCoordSysModelInfo(dataZoomModel: DataZoomModel): {
175	    infoList: DataZoomReferCoordSysInfo[];
176	    // Key: coordSysModel.uid
177	    infoMap: HashMap<DataZoomReferCoordSysInfo, string>;
178	} {
179	    const ecModel = dataZoomModel.ecModel;
180	    const coordSysInfoWrap = {
181	        infoList: [] as DataZoomReferCoordSysInfo[],
182	        infoMap: createHashMap<DataZoomReferCoordSysInfo, string>()
183	    };
184	
185	    dataZoomModel.eachTargetAxis(function (axisDim, axisIndex) {
186	        const axisModel = ecModel.getComponent(getAxisMainType(axisDim), axisIndex) as AxisBaseModel;
187	        if (!axisModel) {
188	            return;
189	        }
190	        const coordSysModel = axisModel.getCoordSysModel();
191	        if (!coordSysModel) {
192	            return;
193	        }
194	
195	        const coordSysUid = coordSysModel.uid;
196	        let coordSysInfo = coordSysInfoWrap.infoMap.get(coordSysUid);
197	        if (!coordSysInfo) {
198	            coordSysInfo = { model: coordSysModel, axisModels: [] };
199	            coordSysInfoWrap.infoList.push(coordSysInfo);
200	            coordSysInfoWrap.infoMap.set(coordSysUid, coordSysInfo);
201	        }
202	
203	        coordSysInfo.axisModels.push(axisModel);
204	    });
205	
206	    return coordSysInfoWrap;
207	}
