221	    private _resetLocation() {
222	        const dataZoomModel = this.dataZoomModel;
223	        const api = this.api;
224	        const showMoveHandle = dataZoomModel.get('brushSelect');
225	        const moveHandleSize = showMoveHandle ? DEFAULT_MOVE_HANDLE_SIZE : 0;
226	
227	        const refContainer = layout.createBoxLayoutReference(dataZoomModel, api).refContainer;
228	
229	        // If some of x/y/width/height are not specified,
230	        // auto-adapt according to target grid.
231	        const coordRect = this._findCoordRect();
232	        const edgeGap = dataZoomModel.get('defaultLocationEdgeGap', true) || 0;
233	        // Default align by coordinate system rect.
234	        const positionInfo = this._orient === HORIZONTAL
235	            ? {
236	                // Why using 'right', because right should be used in vertical,
237	                // and it is better to be consistent for dealing with position param merge.
238	                right: refContainer.width - coordRect.x - coordRect.width,
239	                top: refContainer.height - DEFAULT_FILLER_SIZE - edgeGap - moveHandleSize,
240	                width: coordRect.width,
241	                height: DEFAULT_FILLER_SIZE
242	            }
243	            : { // vertical
244	                right: edgeGap,
245	                top: coordRect.y,
246	                width: DEFAULT_FILLER_SIZE,
247	                height: coordRect.height
248	            };
249	
250	        // Do not write back to option and replace value 'ph', because
251	        // the 'ph' value should be recalculated when resize.
252	        const layoutParams = layout.getLayoutParams(dataZoomModel.option);
253	
254	        // Replace the placeholder value.
255	        each(['right', 'top', 'width', 'height'] as const, function (name) {
256	            if (layoutParams[name] === 'ph') {
257	                layoutParams[name] = positionInfo[name];
258	            }
259	        });
260	
261	        const layoutRect = layout.getLayoutRect(
262	            layoutParams,
263	            refContainer
264	        );
265	
266	        this._location = { x: layoutRect.x, y: layoutRect.y };
267	        this._size = [layoutRect.width, layoutRect.height];
268	        this._orient === VERTICAL && this._size.reverse();
269	    }
