359	    private _updateMinMaxSpan() {
360	        const minMaxSpan = this._minMaxSpan = {} as MinMaxSpan;
361	        const dataZoomModel = this._dataZoomModel;
362	        const dataExtent = this._dataExtent;
363	
364	        each(['min', 'max'], function (minMax) {
365	            let percentSpan = dataZoomModel.get(minMax + 'Span' as 'minSpan' | 'maxSpan');
366	            let valueSpan = dataZoomModel.get(minMax + 'ValueSpan' as 'minValueSpan' | 'maxValueSpan');
367	            valueSpan != null && (valueSpan = this.getAxisModel().axis.scale.parse(valueSpan));
368	
369	            // minValueSpan and maxValueSpan has higher priority than minSpan and maxSpan
370	            if (valueSpan != null) {
