377	                    percentSpan, [0, 100], dataExtent, true
378	                ) - dataExtent[0];
379	            }
380	
381	            minMaxSpan[minMax + 'Span' as 'minSpan' | 'maxSpan'] = percentSpan;
382	            minMaxSpan[minMax + 'ValueSpan' as 'minValueSpan' | 'maxValueSpan'] = valueSpan;
