416	function calculateDataExtent(axisProxy: AxisProxy, axisDim: string, seriesModels: SeriesModel[]) {
417	    const dataExtent = [Infinity, -Infinity];
418	
419	    each(seriesModels, function (seriesModel) {
420	        unionAxisExtentFromData(dataExtent, seriesModel.getData(), axisDim);
421	    });
422	
423	    // It is important to get "consistent" extent when more then one axes is
424	    // controlled by a `dataZoom`, otherwise those axes will not be synchronized
425	    // when zooming. But it is difficult to know what is "consistent", considering
426	    // axes have different type or even different meanings (For example, two
427	    // time axes are used to compare data of the same date in different years).
428	    // So basically dataZoom just obtains extent by series.data (in category axis
429	    // extent can be obtained from axis.data).
430	    // Nevertheless, user can set min/max/scale on axes to make extent of axes
431	    // consistent.
432	    const axisModel = axisProxy.getAxisModel();
433	    const rawExtentResult = ensureScaleRawExtentInfo(axisModel.axis.scale, axisModel, dataExtent).calculate();
434	
435	    return [rawExtentResult.min, rawExtentResult.max] as [number, number];
436	}
