        console.log('BEFORE group', v.group.x, v.group.y, 'loc', JSON.stringify(v._location));
        // Simulate the fix: replace NaN x with size[0]/2 in the shadow shapes.
        const segs = v._displayables.dataShadowSegs;
        for (const g of segs) {
            g.eachChild((child: any) => {
                const pts = child.shape.points;
                for (const p of pts) {
                    if (isNaN(p[0])) { p[0] = v._size[0] / 2; }
                }
                child.dirty();
            });
        }
        v._positionGroup();
        console.log('AFTER group', v.group.x, v.group.y);
        chart.dispose();
    });
});
